def getMaxRepetitions(s1, n1, s2, n2):
    if not n1:
        return 0
    count1, count2, i, j, len1, len2 = 0, 0, 0, 0, len(s1), len(s2)
    visited = {}
    while True:
        if i == 0 and j in visited:
            start_count1, start_count2 = visited[j]
            loop_count1 = count1 - start_count1
            loop_count2 = count2 - start_count2
            repeats = (n1 * len1 - start_count1) // loop_count1
            count1 += repeats * loop_count1
            count2 += repeats * loop_count2
            break
        visited[j] = (count1, count2)
        if s1[i] == s2[j]:
            j += 1
            if j == len2:
                count2 += 1
                j = 0
        i += 1
        if i == len1:
            count1 += 1
            i = 0
            if count1 == n1:
                break
    return count2 // n2
